def transform(grid):
    out = [row[:] for row in grid]
    starts = [1, 5, 9, 13]

    left_masks = []
    objects = []
    for y in starts:
        left_masks.append(tuple(
            grid[y + r][c + 1] == 0
            for r in range(3) for c in range(3)
        ))

        cells = []
        color = 0
        for r in range(3):
            for c in range(3):
                value = grid[y + r][c + 6]
                cells.append(value != 0)
                if value:
                    color = value
        objects.append((tuple(cells), color))

    # Match each left pattern to an object of the same shape. Any unmatched
    # patterns and objects are paired in their original order.
    assignment = [None] * 4
    unused = set(range(4))
    for i, mask in enumerate(left_masks):
        for j in sorted(unused):
            if objects[j][0] == mask:
                assignment[i] = j
                unused.remove(j)
                break

    remaining_rows = [i for i, j in enumerate(assignment) if j is None]
    remaining_objects = sorted(unused)
    for i, j in zip(remaining_rows, remaining_objects):
        assignment[i] = j

    for i, y in enumerate(starts):
        shape, color = objects[assignment[i]]
        for r in range(3):
            for c in range(3):
                out[y + r][c + 6] = color if shape[r * 3 + c] else 0

    return out
