def transform(grid):
    h, width = len(grid), len(grid[0])
    frame = grid[0][0]

    # The left panel is the run of frame-colored cells across the top row.
    panel_width = 0
    while panel_width < width and grid[0][panel_width] == frame:
        panel_width += 1

    separators = [
        r for r in range(h)
        if all(grid[r][c] == frame for c in range(panel_width))
    ]
    inner_width = panel_width - 2
    object_x = panel_width + 1
    objects = {}

    # Record each right-side shape by its occupancy pattern.
    for top, bottom in zip(separators, separators[1:]):
        ys = range(top + 1, bottom)
        mask = tuple(
            tuple(grid[y][x] != 0 for x in range(object_x, object_x + inner_width))
            for y in ys
        )
        color = next(
            (grid[y][x] for y in ys
             for x in range(object_x, min(object_x + inner_width, width))
             if grid[y][x] != 0),
            0
        )
        objects.setdefault(mask, []).append(color)

    out = [row[:panel_width] for row in grid]
    for top, bottom in zip(separators, separators[1:]):
        ys = range(top + 1, bottom)
        mask = tuple(
            tuple(grid[y][x] == 0 for x in range(1, panel_width - 1))
            for y in ys
        )
        matches = objects.get(mask, [])
        color = matches.pop(0) if matches else 0

        if color:
            for y in ys:
                for x in range(1, panel_width - 1):
                    if grid[y][x] == 0:
                        out[y][x] = color

    return out
